INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'7504', E'8867', E'report', E'Weekly report', E'SABIR MOHAMMED S', E'sabir', E'SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69', E'employee', E'PCB Fabrication Engineer', E'MIB04', E'PCB Designs & Fabrication Team', E'9626272076', '{"description": "WEEKLY WORK REPORT\nEmployee Name: Sabir Mohamed\nReporting Period: 23 October 2026 \u2013 24 October 2026\n1. TEQTIS INFO Project \u2013 PDB Design Workflow and Analysis\nPrepared the project workflow for the Dual-Battery Power Distribution Board (PDB) design.\nConducted an initial analysis of the project requirements, engineering activities, and development procedures.\nReviewed the proposed work sequence and identified key tasks required for project execution.\nParticipated in a technical discussion with Advisor Surya and Managing Partner Hareesh regarding project requirements, development approaches, work allocation, and engineering resources.\nAnalysed the scope of work for the upcoming TEQTIS project to support planning and execution.\n2. Four-Layer PCB Design \u2013 Altium Designer\nContinued development of the four-layer PCB design using Altium Designer.\nWorked on component footprint modifications and customization.\nPerformed schematic debugging and validation to identify circuit connection errors and design inconsistencies.\nCarried out design corrections and verification to improve schematic accuracy and prepare the design for further PCB development.\n3. Student Communication and Project Coordination\nCommunicated with students regarding their project requirements and progress.\nExplained the company brochure and provided information about the company''s services and project offerings.\nClarified student queries related to projects and available services.\nDiscussed project confirmation and pricing with a student.\nFollowed up on the student''s pricing concerns and documented the difficulty in proceeding at the quoted price.\n4. Engineering College Data Collection\nContinued collecting information related to engineering colleges.\nOrganized the collected data for company records and future reference.\nMaintained progress on data collection activities to support future company outreach and project-related initiatives.\n5. Company Project Activities\nContinued working on ongoing company projects.\nFollowed up on project-related tasks and reviewed upcoming development requirements.\nAnalysed project scope and activities to support work planning and execution.\nWeekly Work Summary\nDuring the reporting period, work focused on technical project development, PCB design and schematic validation, TEQTIS INFO project planning, student communication, project pricing discussions, and engineering college data collection.\nProgress was made in reviewing engineering requirements, identifying design corrections, planning upcoming project activities, and supporting company outreach initiatives.\nOverall Status\nStatus: Ongoing project activities and assigned tasks progressed during the reporting period.\nPlan for the Next Week\nContinue the four-layer PCB design, including schematic validation, footprint corrections, and layout development.\nProceed with TEQTIS INFO project planning and detailed analysis of the Dual-Battery PDB design requirements.\nFollow up on project discussions and coordinate the next engineering activities with the relevant team members.\nContinue engineering college data collection and organize the information for company use.\nFollow up with students regarding project requirements, confirmations, and pricing wherever applicable.\nReport Prepared By: Sabir Mohamed", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 44, "periodStartDate": "2026-10-26", "periodEndDate": "2026-11-01", "periodLabel": "2026-10-26", "reportDate": "2026-10-26", "attachments": [], "approvalChain": ["hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 2, "comments": [{"by": "gkbharath", "comment": "1,2,4 are others work.", "decision": "reject", "stageIndex": 2, "at": "2026-10-26T04:34:19.912Z"}, {"by": "santhanakumarv", "comment": "Subject to Review.", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T04:31:48.899Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 0, "at": "2026-10-26T04:26:18.590Z"}]}'::jsonb, E'', E'admin', E'rejected', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T04:18:30.920Z', E'2026-10-26T04:34:19.914Z') ON CONFLICT ("id") DO NOTHING;
