INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'4205', E'2851', E'report', E'Weekly Work Report – Student Project Coordination and Engineering College Data Collection (19–24 October 2026)', E'MATHIYAZHAGAN D', E'mathi', E'SMIB-EMP-ece437f0-46b4-4c26-acda-c6164dadef01', E'intern', E'PCB Design Intern', E'MIB06', E'PCB Designs & Fabrication Team', E'8056197704', '{"description": "During the reporting period from 19 October to 24 October 2026, I worked on student project coordination, project collection follow-ups, company brochure explanation, and engineering college data collection across four states.\n\nI contacted students regarding project collection and discussed their project requirements. I explained the company brochure and services to students and followed up on project confirmation. During one confirmation discussion, a student raised a concern that the quoted project price was too high, and the project was not confirmed at the proposed price.\n\nAlongside student communication, I continued project-related activities for the company and collected and organized engineering college data to support future college outreach, training proposals, and institutional business development.\n\nThe same ongoing work activities were carried out on 19, 20, and 21 October, followed by the above activities during 22\u201324 October.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 43, "periodStartDate": "2026-10-19", "periodEndDate": "2026-10-25", "periodLabel": "2026-10-24", "reportDate": "2026-10-24", "attachments": [{"name": "Report.pdf", "size": 35591, "type": "application/pdf", "base64": ""}], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-26T05:32:33.535Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T05:29:33.207Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T05:28:29.874Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T05:15:40.197Z"}]}'::jsonb, E'This report summarizes the work completed and ongoing activities during the week. The main objectives were to coordinate with students regarding projects, explain the company’s services, follow up on project confirmation, and continue engineering college data collection across four states.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T04:08:08.362Z', E'2026-10-26T05:32:33.536Z') ON CONFLICT ("id") DO NOTHING;
