INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'4212', E'7736', E'report', E'weekly report (Reporting Period: 08 October 2026, 10 October 2026)', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'intern', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"description": "1. Introduction\nThis report summarizes the joining formalities, initial work orientation, and technical workshop activities carried out on 08 October 2026 and 10 October 2026 as part of my professional responsibilities at SURYA\u2019S MiB ENTERPRISES.\n2. Activities on 08 October 2026 \u2013 Joining and Induction\nVenue: Mudhalvar Padaipagam\nTime: 10:00 AM onwards\nI formally joined SURYA\u2019S MiB ENTERPRISES on 08 October 2026 as a PCB & EMS / IoT Engineer / Designer \u2013 T.\nThe day''s activities included:\nSubmission of the required documents and completion of document verification.\nReceipt of the joining letter from Advisor Surya and Managing Partner Hareesh V.\nAn initial discussion regarding the organization''s work nature, technical responsibilities, and upcoming assignments.\nThe induction process provided an initial understanding of the organization''s expectations and the responsibilities associated with my position.\n3. Activities on 10 October 2026 \u2013 Hands-on Technical Workshop\nVenue: AMS College of Engineering, Avadi\nTeam Members: Vishnu Varshini M, Sabir Mohamed, and Managing Partner Hareesh V\nOn 10 October 2026, I participated in conducting a practical technical workshop at AMS College of Engineering, Avadi, along with team member Sabir Mohamed and Managing Partner Hareesh V.\nThe workshop focused on providing students with practical exposure to electronics and IoT-based project development.\nKey activities conducted\nWorkshop Setup and Coordination: Took over and coordinated the workshop activities at the college along with the team.\nHands-on Project Training: Guided students through the implementation of three mini projects, providing practical demonstrations and hands-on learning opportunities.\nProject Testing and Verification: Tested the completed mini projects to verify their functionality and demonstrate the working principles to the students.\nStudent Interaction: Supported practical learning by explaining project implementation and helping students understand the functioning of the developed systems.\nCertificate Distribution: Concluded the workshop activities with the distribution of certificates to the participating students.\nThe workshop provided students with practical experience in project implementation and testing while supporting their understanding of applied electronics and IoT concepts.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 41, "periodStartDate": "2026-10-05", "periodEndDate": "2026-10-11", "periodLabel": "2026-10-08", "reportDate": "2026-10-08", "attachments": [], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-26T05:31:40.701Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T05:27:46.469Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T05:25:57.515Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T05:15:44.360Z"}]}'::jsonb, E'', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T03:45:56.043Z', E'2026-10-26T05:31:40.701Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'7789', E'4107', E'report', E'weekly report (Reporting Period: 14 October 2026 – 17 October 2026)', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'intern', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"description": "1. Introduction\nThis report summarizes the technical, quotation-preparation, marketing research, and business-development activities carried out from 14 October 2026 to 17 October 2026 as part of my responsibilities at SURYA\u2019S MiB ENTERPRISES.\n2. Activities on 14 October 2026 \u2013 Marketing Research, Quotations and Design File Analysis\nThe day''s activities focused on CMRL marketing research, preparation of project quotations, and initial analysis of a four-layer PCB design file.\n\uf0b7CMRL Marketing Research: Worked on gathering marketing-related details and reviewing potential opportunities for promoting the organization''s products.\n\uf0b7Quotation Preparation for JSON Design Files: Prepared a quotation based on the provided JSON design files.\n\uf0b7Induction Motor Control PCB Quotation: Worked on a quotation for a 230 VAC, single-phase induction motor control PCB project.\n\uf0b7Four-Layer PCB File Analysis: Analysed the provided four-layer PCB JSON file in EasyEDA to review the design and identify items requiring further checking.\n3. Activities on 15 October 2026 \u2013 Four-Layer PCB Debugging and DRC Analysis\nThe day''s work concentrated on debugging and checking the four-layer PCB project using KiCad.\n\uf0b7Design Debugging: Examined the four-layer project in KiCad and investigated design errors requiring correction.\n\uf0b7Error Analysis: Reviewed the identified issues to support further PCB design corrections.\n\uf0b7DRC Report: Generated and reviewed the Design Rule Check (DRC) report to identify reported PCB design-rule violations and guide the correction process.\n4. Activities on 16 October 2026 \u2013 Company Database and Quotation Preparation\nThe day''s activities focused on business development and preparation of a quotation for a controller project.\n\uf0b7Company Database Creation: Continued building a structured database of companies associated with electronics, embedded systems, IoT, firmware, and PCB-related services.\n\uf0b7Company Outreach: Contacted companies to explore potential business opportunities and orders for the organization.\n\uf0b7Hybrid Urinal Controller Quotation: Prepared a quotation for the hybrid urinal controller project based on the available project requirements.\n5. Activities on 17 October 2026 \u2013 Altium PCB Design and Database Development\nThe day''s work involved continuing the four-layer PCB design in Altium Designer alongside company database activities.\n\uf0b7Four-Layer PCB Design: Worked on developing the four-layer PCB layout in Altium Designer.\n\uf0b7Design Review and Progress: Continued the design workflow and reviewed the layout as part of the ongoing PCB design task.\n\uf0b7Company Database Work: Continued organizing and updating company information to support business development and outreach.\n6. Conclusion\nDuring the reporting period, I worked on CMRL marketing research, multiple PCB-related quotations, and the analysis and debugging of a four-layer PCB project using EasyEDA and KiCad. I also prepared a DRC report, continued the four-layer design in Altium Designer, and contributed to company database development and outreach for potential orders. These activities supported both the organization''s technical design work and its business-development efforts.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 42, "periodStartDate": "2026-10-12", "periodEndDate": "2026-10-18", "periodLabel": "2026-10-14", "reportDate": "2026-10-14", "attachments": [], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-26T05:31:53.106Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T05:29:36.273Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T05:28:48.162Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T05:15:48.126Z"}]}'::jsonb, E'', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T03:43:20.098Z', E'2026-10-26T05:31:53.106Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'4601', E'8676', E'report', E'weekly report (Reporting Period: 19–24 October 2026)', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'intern', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"description": "19 October 2026 \u2013 Monday\nContinued electronics and PCB-related project activities and reviewed ongoing work requirements.\nReviewed project requirements and supported ongoing quotation preparation and PCB design activities.\n21 October 2026 \u2013 Wednesday\nPrepared project quotations based on the specified technical requirements.\nDeveloped and updated the company database for business development and potential customer outreach.\nWorked on debugging errors and schematic development for the four-layer PCB project in Altium Designer.\n22 October 2026 \u2013 Thursday\nPrepared a quotation for the Dual-Battery Power Distribution Board (PDB) Design Project.\nModified and customized component footprints in Altium Designer to improve design consistency and resolve schematic/PCB-related issues.\n23 October 2026 \u2013 Friday\nPrepared the workflow and technical analysis for the upcoming TEQTIS INFO PDB Design Project.\nAttended a project discussion with Advisor Surya and Managing Partner Hareesh regarding the TEQTIS INFO project requirements and scope.\nContinued working on the four-layer PCB project in Altium Designer.\n24 October 2026 \u2013 Saturday\nDebugged and validated the schematic of the four-layer PCB project in Altium Designer.\nAnalysed the scope of work, technical requirements, and proposed activities for the upcoming TEQTIS INFO project.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 44, "periodStartDate": "2026-10-26", "periodEndDate": "2026-11-01", "periodLabel": "2026-10-26", "reportDate": "2026-10-26", "attachments": [], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "comments": [{"by": "gkbharath", "comment": "Subject to Check the Schematic Files Made By She.", "decision": "approve", "stageIndex": 3, "at": "2026-10-26T10:49:11.445Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T05:21:36.124Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T05:20:32.343Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T05:15:52.981Z"}]}'::jsonb, E'', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T03:40:30.066Z', E'2026-10-26T10:49:11.445Z') ON CONFLICT ("id") DO NOTHING;
